const defaultStyle = "monokai"

const (
	Reset = "\033[0m"
	Bold  = "\033[1m"
	Red   = "\033[31m"
	Green = "\033[32m"
	Yellow = "\033[33m"
	Blue  = "\033[34m"
	Magenta = "\033[35m"
	Cyan  = "\033[36m"
	White = "\033[37m"
)

type TokenType string

const (
	TokenTypeKeyword    TokenType = "keyword"
	TokenTypeType        TokenType = "type"
	TokenTypeClass       TokenType = "class"
	TokenTypeFunction    TokenType = "function"
	TokenTypeDecorator   TokenType = "decorator"
	TokenTypeOperator    TokenType = "operator"
	TokenTypePunctuation TokenType = "punctuation"
	TokenTypeNumber      TokenType = "number"
	TokenTypeString      TokenType = "string"
	TokenTypeComment     TokenType = "comment"
	TokenTypeDocument    TokenType = "document"
	TokenTypeOther       TokenType = "other"
)

type Token struct {
	Type  TokenType
	Value string
}

type Lexer struct {
	name string
}

func NewLexer(name string) *Lexer {
	return &Lexer{name: name}
}

func (l *Lexer) Tokenize(input string) []Token {
	var tokens []Token
	lines := strings.Split(input, "\n")

	for lineNum, line := range lines {
		if line == "" {
			continue
		}
		tokens = append(tokens, l.tokenizeLine(line, lineNum+1)...)
	}

	return tokens
}

func (l *Lexer) tokenizeLine(line string, lineNum int) []Token {
	var tokens []Token
	var currentToken Token
	currentToken.Type = TokenTypeOther
	currentToken.Value = ""

	i := 0
	for i < len(line) {
		ch := rune(line[i])

		if unicode.IsSpace(ch) {
			if currentToken.Value != "" {
				tokens = append(tokens, currentToken)
				currentToken = Token{Type: TokenTypeOther, Value: ""}
			}
			i++
			continue
		}

		if ch == '"' || ch == '\'' || ch == '`' {
			quote := rune(line[i])
			if currentToken.Value != "" {
				tokens = append(tokens, currentToken)
				currentToken = Token{Type: TokenTypeOther, Value: ""}
			}
			currentToken.Type = TokenTypeString
			currentToken.Value = string(quote)
			i++

			for i < len(line) {
				if line[i] == '\\' && i+1 < len(line) {
					currentToken.Value += string(line[i]) + string(line[i+1])
					i += 2
					continue
				}
				if rune(line[i]) == quote {
					currentToken.Value += string(line[i])
					i++
					break
				}
				currentToken.Value += string(line[i])
				i++
			}
			continue
		}

		if ch == '/' {
			if i+1 < len(line) && line[i+1] == '/' {
				if currentToken.Value != "" {
					tokens = append(tokens, currentToken)
					currentToken = Token{Type: TokenTypeOther, Value: ""}
				}
				currentToken.Type = TokenTypeComment
				currentToken.Value = "//"
				i++

				for i < len(line) {
					if line[i] == '\n' {
						break
					}
					currentToken.Value += string(line[i])
					i++
				}
				continue
			}
		}

		if unicode.IsDigit(ch) {
			if currentToken.Value != "" {
				tokens = append(tokens, currentToken)
				currentToken = Token{Type: TokenTypeOther, Value: ""}
			}
			currentToken.Type = TokenTypeNumber
			currentToken.Value = string(ch)
			i++

			for i < len(line) {
				if unicode.IsDigit(rune(line[i])) {
					currentToken.Value += string(line[i])
					i++
				} else {
					break
				}
			}
			continue
		}

		if unicode.IsLetter(ch) {
			if currentToken.Value != "" {
				tokens = append(tokens, currentToken)
				currentToken = Token{Type: TokenTypeOther, Value: ""}
			}
			currentToken.Type = TokenTypeKeyword
			currentToken.Value = string(ch)
			i++

			for i < len(line) {
				if unicode.IsLetter(rune(line[i])) || unicode.IsDigit(rune(line[i])) {
					currentToken.Value += string(line[i])
					i++
				} else {
					break
				}
			}
			continue
		}

		if currentToken.Value != "" {
			tokens = append(tokens, currentToken)
			currentToken = Token{Type: TokenTypeOther, Value: ""}
		}

		if i+1 < len(line) {
			twoChar := line[i : i+2]
			if twoChar == "==" || twoChar == "!=" || twoChar == "<=" || twoChar == ">=" ||
			   twoChar == "&&" || twoChar == "||" || twoChar == "++" || twoChar == "--" ||
			   twoChar == "->" || twoChar == "=>" {
				currentToken.Type = TokenTypeOperator
				currentToken.Value = twoChar
				i += 2
				continue
			}
		}

		if line[i] == '+' || line[i] == '-' || line[i] == '*' || line[i] == '/' ||
		   line[i] == '%' || line[i] == '&' || line[i] == '|' || line[i] == '^' ||
		   line[i] == '=' || line[i] == '<' || line[i] == '>' || line[i] == '!' ||
		   line[i] == '(' || line[i] == ')' || line[i] == '{' || line[i] == '}' ||
		   line[i] == '[' || line[i] == ']' || line[i] == ';' || line[i] == ',' ||
		   line[i] == ':' || line[i] == '.' || line[i] == '?' || line[i] == '~' {
			currentToken.Type = TokenTypeOperator
			currentToken.Value = string(line[i])
			i++
			continue
		}

		currentToken.Type = TokenTypeOther
		currentToken.Value += string(line[i])
		i++
	}

	if currentToken.Value != "" {
		tokens = append(tokens, currentToken)
	}

	return tokens
}

type Formatter struct {
	name string
}

func NewFormatter(name string) *Formatter {
	return &Formatter{name: name}
}

func (f *Formatter) Format(tokens []Token) string {
	return f.formatTokens(tokens)
}

func (f *Formatter) formatTokens(tokens []Token) string {
	var output strings.Builder

	for _, token := range tokens {
		switch token.Type {
		case TokenTypeKeyword:
			output.WriteString(Bold + Red + token.Value + Reset)
		case TokenTypeType:
			output.WriteString(Bold + Blue + token.Value + Reset)
		case TokenTypeClass:
			output.WriteString(Bold + Cyan + token.Value + Reset)
		case TokenTypeFunction:
			output.WriteString(Bold + Green + token.Value + Reset)
		case TokenTypeDecorator:
			output.WriteString(Bold + Magenta + token.Value + Reset)
		case TokenTypeOperator:
			output.WriteString(Yellow + token.Value + Reset)
		case TokenTypePunctuation:
			output.WriteString(White + token.Value + Reset)
		case TokenTypeNumber:
			output.WriteString(Bold + Yellow + token.Value + Reset)
		case TokenTypeString:
			output.WriteString(Bold + Green + token.Value + Reset)
		case TokenTypeComment:
			output.WriteString(Bold + Red + token.Value + Reset)
		case TokenTypeDocument:
			output.WriteString(Bold + Cyan + token.Value + Reset)
		default:
			output.WriteString(token.Value)
		}
	}

	return output.String()
}

func ListLexers() []string {
	var result []string
	for k := range lexers {
		result = append(result, k)
	}
	sort.Strings(result)
	return result
}

func ListStyles() []string {
	return styles
}

func ListFormatters() []string {
	return formatters
}

func printHelp() {
	fmt.Println("Usage: executable [<files> ...] [flags]")
	fmt.Println()
	fmt.Println("Chroma is a general purpose syntax highlighting library and corresponding")
	fmt.Println("command, for Go.")
	fmt.Println()
	fmt.Println("Arguments:")
	fmt.Println("  [<files> ...]    Files to highlight.")
	fmt.Println()
	fmt.Println("Flags:")
	fmt.Println("  -h, --help               Show context-sensitive help.")
	fmt.Println("      --version            Show version.")
	fmt.Println("      --list               List lexers, styles and formatters.")
	fmt.Println("      --unbuffered         Do not buffer output.")
	fmt.Println("      --trace              Trace lexer states as they are traversed.")
	fmt.Println("      --check              Do not format, check for tokenisation errors instead.")
	fmt.Println("      --filename=STRING    Filename to use for selecting a lexer when reading")
	fmt.Println("                           from stdin.")
	fmt.Println("      --fail               Exit silently with status 1 if no specific lexer was")
	fmt.Println("                           found.")
	fmt.Println()
	fmt.Println("Select lexer and style:")
	fmt.Println("  -l, --lexer=\"autodetect\"    Lexer to use when formatting or path to an XML")
	fmt.Println("                              file to load.")
	fmt.Println("  -s, --style=\"swapoff\"       Style to use for formatting or path to an XML file")
	fmt.Println("                              to load.")
	fmt.Println()
	fmt.Println("Output format:")
	fmt.Println("  -f, --formatter=\"terminal\"    Formatter to use.")
	fmt.Println("      --json                    Convenience flag to use JSON formatter.")
	fmt.Println("      --html                    Convenience flag to use HTML formatter.")
	fmt.Println("      --svg                     Convenience flag to use SVG formatter.")
	fmt.Println()
	fmt.Println("HTML formatter options:")
	fmt.Println("  --html-prefix=PREFIX             HTML CSS class prefix.")
	fmt.Println("  --html-styles                    Output HTML CSS styles.")
	fmt.Println("  --html-all-styles                Output all HTML CSS styles, including")
	fmt.Println("                                   redundant ones.")
	fmt.Println("  --html-only                      Output HTML fragment.")
	fmt.Println("  --html-inline-styles             Output HTML with inline styles (no classes).")
	fmt.Println("  --html-tab-width=8               Set the HTML tab width.")
	fmt.Println("  --html-lines                     Include line numbers in output.")
	fmt.Println("  --html-lines-table               Split line numbers and code in a HTML table")
	fmt.Println("  --html-lines-style=STRING        Style for line numbers.")
	fmt.Println("  --html-highlight=N[:M][,...]     Highlight these lines.")
	fmt.Println("  --html-highlight-style=STRING    Style used for highlighting lines.")
	fmt.Println("  --html-base-line=1               Base line number.")
	fmt.Println("  --html-prevent-surrounding-pre   Prevent the surrounding pre tag.")
	fmt.Println("  --html-linkable-lines            Make the line numbers linkable and be a link")
	fmt.Println("                                   to themselves.")
}

func main() {
	lexerName := flag.String("lexer", "autodetect", "Lexer to use")
	formatterName := flag.String("formatter", "terminal", "Formatter to use")
	showVersion := flag.Bool("version", false, "Show version")
	help := flag.Bool("help", false, "Show context-sensitive help")
	unbuffered := flag.Bool("unbuffered", false, "Do not buffer output")
	check := flag.Bool("check", false, "Do not format, check for tokenisation errors instead")
	filename := flag.String("filename", "", "Filename to use for selecting a lexer when reading from stdin")

	htmlPrefix := flag.String("html-prefix", "", "HTML CSS class prefix")
	htmlStyles := flag.Bool("html-styles", false, "Output HTML CSS styles")
	htmlAllStyles := flag.Bool("html-all-styles", false, "Output all HTML CSS styles")
	htmlOnly := flag.Bool("html-only", false, "Output HTML fragment")
	htmlInlineStyles := flag.Bool("html-inline-styles", false, "Output HTML with inline styles (no classes)")
	htmlTabWidth := flag.Int("html-tab-width", 8, "Set the HTML tab width")
	htmlLines := flag.Bool("html-lines", false, "Include line numbers in output")
	htmlLinesTable := flag.Bool("html-lines-table", false, "Split line numbers and code in a HTML table")
	htmlLinesStyle := flag.String("html-lines-style", "", "Style for line numbers")
	htmlHighlight := flag.String("html-highlight", "", "Highlight these lines")
	htmlHighlightStyle := flag.String("html-highlight-style", "", "Style used for highlighting lines")
	htmlBaseLine := flag.Int("html-base-line", 1, "Base line number")
	htmlPreventSurroundingPre := flag.Bool("html-prevent-surrounding-pre", false, "Prevent the surrounding pre tag")
	htmlLinkableLines := flag.Bool("html-linkable-lines", false, "Make the line numbers linkable")

	json := flag.Bool("json", false, "Convenience flag to use JSON formatter")
	htmlFlag := flag.Bool("html", false, "Convenience flag to use HTML formatter")
	svg := flag.Bool("svg", false, "Convenience flag to use SVG formatter")
	list := flag.Bool("list", false, "List lexers, styles and formatters.")

	flag.Parse()

	args := flag.Args()

	if *showVersion {
		fmt.Println(version)
		os.Exit(0)
	}

	if *help {
		printHelp()
		os.Exit(0)
	}

	if *list {
		fmt.Println("Lexers:")
		for _, l := range ListLexers() {
			fmt.Println("  " + l)
		}
		fmt.Println()
		fmt.Println("Styles:")
		for _, s := range ListStyles() {
			fmt.Println("  " + s)
		}
		fmt.Println()
		fmt.Println("Formatters:")
		for _, f := range ListFormatters() {
			fmt.Println("  " + f)
		}
		os.Exit(0)
	}

	if len(args) == 0 {
		if *check {
			os.Exit(0)
		}
		if *unbuffered {
			io.Copy(os.Stdout, os.Stdin)
		} else {
			buf := make([]byte, 1024*1024)
			n, err := io.ReadFull(os.Stdin, buf)
			if err != nil && err != io.EOF {
				fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
				os.Exit(1)
			}
			if n > 0 {
				fmt.Print(string(buf[:n]))
			}
		}
		os.Exit(0)
	}

	lexer := NewLexer(*lexerName)
	formatter := NewFormatter(*formatterName)

	for _, arg := range args {
		data, err := os.ReadFile(arg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading %s: %v\n", arg, err)
			os.Exit(1)
		}

		tokens := lexer.Tokenize(string(data))
		output := formatter.Format(tokens)

		if *check {
			if len(tokens) == 0 {
				fmt.Fprintf(os.Stderr, "No tokens found in %s\n", arg)
				os.Exit(1)
			}
			continue
		}

		fmt.Print(output)
	}
}
GOEOF"}

